import torch,torch.nn as nn; exec("class GroupedQueryAttention(nn.Module):\n    def __init__(self, model_dim, num_heads, num_kv_heads):\n        super().__init__()\n        torch.manual_seed(0)\n        self.num_heads = num_heads\n        self.num_kv_heads = num_kv_heads\n        self.head_dim = model_dim // num_heads\n        self.q_proj = nn.Linear(model_dim, model_dim, bias=False)\n        self.k_proj = nn.Linear(model_dim, num_kv_heads * self.head_dim, bias=False)\n        self.v_proj = nn.Linear(model_dim, num_kv_heads * self.head_dim, bias=False)\n        self.out_proj = nn.Linear(model_dim, model_dim, bias=False)\n    def forward(self, x):\n        B, T, D = x.shape\n        Q = self.q_proj(x).view(B, T, self.num_heads, self.head_dim).transpose(1, 2)\n        K = self.k_proj(x).view(B, T, self.num_kv_heads, self.head_dim).transpose(1, 2)\n        V = self.v_proj(x).view(B, T, self.num_kv_heads, self.head_dim).transpose(1, 2)\n        repeat = self.num_heads // self.num_kv_heads\n        K = K.repeat_interleave(repeat, dim=1)\n        V = V.repeat_interleave(repeat, dim=1)\n        scores = Q @ K.transpose(-2, -1) / (self.head_dim ** 0.5)\n        mask = torch.triu(torch.ones(T, T), diagonal=1).bool()\n        scores = scores.masked_fill(mask, float('-inf'))\n        attn = torch.softmax(scores, dim=-1)\n        out = attn @ V\n        out = out.transpose(1, 2).contiguous().view(B, T, D)\n        return torch.round(self.out_proj(out), decimals=4)")